function endpointDomain(endpoint){const nets=buildNets(project),group=nets.nets.find(n=>n.endpoints.includes(endpoint));if(group?.domain)return group.domain;return group?.endpoints.some(e=>{const [id,pin]=e.split(':');const c=project.circuit.components.find(c=>c.id===id);return c&&getPins(c).find(p=>p.id===pin)?.domain==='digital';})?'digital':'analog';}
