function renderParts(query=''){$('part-count').textContent=String(LIBRARY.length);const filtered=LIBRARY.filter(p=>(p.name+' '+p.type+' '+p.category+' '+p.description).toLowerCase().includes(query.toLowerCase()));let category='';$('parts-list').innerHTML=filtered.map(p=>{const heading=p.category!==category?`<h3 class="part-category">${esc(p.category)}</h3>`:'';category=p.category;let symbol;try{symbol=symbolThumbnail(p.type);}catch{symbol=esc(p.type);}return heading+`<button class="part-button" data-part="${p.type}" title="${esc(p.description)}"><span class="part-symbol">${symbol}</span><span>${esc(p.name)}<small>${esc(p.defaults.value??(p.type==='DVS'?'0 / 1 · switchable':p.type==='DLED'?'Red when HIGH':['V','I'].includes(p.type)?'DC · sine · pulse · PWL':['ADC','DAC'].includes(p.type)?'1-bit bridge':p.pins.some(pin=>pin.domain==='digital')?'0 · 1 · X · Z':p.model?'Generic model':p.type==='GND'?'Node 0':'Ideal element'))}</small></span></button>`;}).join('')||'<p class="helper">No matching parts. Try “source” or “resistor”.</p>';$('parts-list').querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{editor.place(b.dataset.part);$('empty-state').hidden=true;status(`Place ${getPart(b.dataset.part).name}: click the grid, or focus the grid and press Enter.`);editor.focus();});}
