function showLUTEditor(componentId){
 const component=project.circuit.components.find(c=>c.id===componentId);
 if(!component||component.type!=='LUT')return;
 const defaults=getPart('LUT').defaults,dimension=(value,max,fallback)=>{const n=Number(value);return Number.isInteger(n)&&n>=1&&n<=max?n:Number(fallback);},originalTable=String(component.params.table??'');
 let inputBits=dimension(component.params.inputBits,4,defaults.inputBits),outputBits=dimension(component.params.outputBits,8,defaults.outputBits),rows;
 const readRows=()=>normalizeLUTRows([...$('dialog-content').querySelectorAll('[data-lut-row]')].map(input=>input.value),outputBits);
 const draw=()=>{
  showDialog(`${component.ref} · edit truth table`,`<p>Define every binary input combination. Each output is an MSB-first word using 0, 1, X or Z.</p><div class="field-row"><label class="field">Input bits<select id="lut-input-bits">${[1,2,3,4].map(n=>`<option value="${n}" ${n===inputBits?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Output bits<select id="lut-output-bits">${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}" ${n===outputBits?'selected':''}>${n}</option>`).join('')}</select></label></div><p class="helper">Changing dimensions keeps the lowest-address rows and least-significant output bits, adding zeros where needed. Review every row before applying. Connected pin widths must still agree.</p><div id="lut-rows">${lutRowsHTML(rows,inputBits,outputBits)}</div><p id="lut-error" class="error-inline" role="status"></p><div class="dialog-actions"><button id="lut-cancel">Cancel</button><button id="lut-apply" class="primary">Apply truth table</button></div>`);
  const resize=()=>{try{const old=readRows();inputBits=Number($('lut-input-bits').value);outputBits=Number($('lut-output-bits').value);rows=Array.from({length:2**inputBits},(_,i)=>(old[i]??'').slice(-outputBits).padStart(outputBits,'0'));draw();}catch(error){$('lut-input-bits').value=String(inputBits);$('lut-output-bits').value=String(outputBits);$('lut-error').textContent=error.message;}};
  $('lut-input-bits').onchange=resize;$('lut-output-bits').onchange=resize;$('lut-cancel').onclick=()=>$('dialog').close();
  $('lut-apply').onclick=()=>{try{const changes={inputBits:String(inputBits),outputBits:String(outputBits),table:buildTruthTable(readRows(),inputBits,outputBits)},candidate=clone(project);setComponentParams(candidate,componentId,changes);validateProject(candidate);$('dialog').close();commit(p=>setComponentParams(p,componentId,changes),`${component.ref} truth table updated. Run to see the result.`);}catch(error){$('lut-error').textContent=error.message;}};
 };
 const repair=message=>{
  showDialog(`${component.ref} · repair truth table`,`<p>The saved table needs correction before it can open in the row editor. The original text is preserved below. Changes here are a local draft; the component changes only after <strong>Apply truth table</strong> in the row editor.</p><div class="field-row"><label class="field">Input bits<select id="lut-repair-input-bits">${[1,2,3,4].map(n=>`<option value="${n}" ${n===inputBits?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Output bits<select id="lut-repair-output-bits">${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}" ${n===outputBits?'selected':''}>${n}</option>`).join('')}</select></label></div><label class="field">Table text · local draft<textarea id="lut-repair-text" rows="8" spellcheck="false">${esc(originalTable)}</textarea></label><p class="helper">Provide every binary input address once, for example 00:00; 01:01; 10:01; 11:10. Output words may use 0, 1, X, Z or a supported numeric prefix.</p><details><summary>Original saved table text</summary><pre>${esc(originalTable)}</pre></details><p id="lut-repair-error" class="error-inline" role="status">${esc(message)}</p><div class="dialog-actions"><button id="lut-repair-cancel">Cancel</button><button id="lut-repair-reset">Reset local draft to zeros</button><button id="lut-repair-open" class="primary">Continue to row editor</button></div>`);
  const dimensions=()=>{inputBits=dimension($('lut-repair-input-bits').value,4,defaults.inputBits);outputBits=dimension($('lut-repair-output-bits').value,8,defaults.outputBits);};
  $('lut-repair-cancel').onclick=()=>$('dialog').close();
  $('lut-repair-open').onclick=()=>{try{dimensions();rows=parseTruthTable($('lut-repair-text').value,inputBits,outputBits);draw();}catch(error){$('lut-repair-error').textContent=error.message;}};
  $('lut-repair-reset').onclick=()=>{dimensions();rows=Array(2**inputBits).fill('0'.repeat(outputBits));draw();};
 };
 try{rows=parseTruthTable(originalTable,inputBits,outputBits);draw();}catch(error){repair(error.message);}
}

function showTruthTables(){
 if(engine.running||preparing||continuousSession?.running){status('Wait for the current experiment or stop it before generating a truth table.');return;}
 let generated,choices;
 try{generated=generateNetlist(project);choices=truthTableChoices(project,generated);}catch(error){choices={inputs:[],outputs:[],reason:error.message};}
 let chosenBits=0;const defaults=new Set();for(const input of choices.inputs)if(chosenBits+input.width<=8){chosenBits+=input.width;defaults.add(input.id);}
 const preferred=choices.outputs.filter(output=>output.preferred),defaultOutputs=new Set((preferred.length?preferred:choices.outputs).slice(0,8).map(output=>output.name));
 const history=truthTables.length?`<section class="truth-history"><h3>Saved truth tables</h3>${[...truthTables].reverse().map(record=>`<button data-truth-history="${esc(record.id)}">Revision ${record.revision} · ${record.result.rows.length} rows · ${esc(new Date(record.completedAt).toLocaleTimeString())}</button>`).join('')}</section>`:'';
 showDialog('Truth table',`<p>Enumerate binary inputs and measure the settled combinational outputs. Select up to eight input bits and 32 output columns. Other constant inputs keep their configured values.</p>${history}${choices.reason?`<div class="notice warning">${esc(choices.reason)}</div>`:`<div class="truth-choice-grid"><fieldset><legend>Inputs to vary</legend>${choices.inputs.map(input=>`<label class="truth-choice"><input type="checkbox" data-truth-input="${esc(input.id)}" ${defaults.has(input.id)?'checked':''}><span>${esc(input.label)}<small>${input.width} bit${input.width===1?'':'s'}</small></span></label>`).join('')}</fieldset><fieldset><legend>Outputs to inspect</legend>${choices.outputs.map(output=>`<label class="truth-choice"><input type="checkbox" data-truth-output="${esc(output.name)}" ${defaultOutputs.has(output.name)?'checked':''}><span>${esc(output.label)}<small>${output.width} bit${output.width===1?'':'s'} · ${esc(output.name)}</small></span></label>`).join('')}</fieldset></div><p id="truth-selection-status" class="helper" role="status"></p><div class="dialog-actions"><button id="truth-generate" class="primary">Generate truth table</button></div>`}`);
 $('dialog-content').querySelectorAll('[data-truth-history]').forEach(button=>button.onclick=()=>showTruthTableRecord(truthTables.find(record=>record.id===button.dataset.truthHistory)));
 if(choices.reason)return;
 const selections=()=>({inputIds:[...$('dialog-content').querySelectorAll('[data-truth-input]:checked')].map(input=>input.dataset.truthInput),outputNames:[...$('dialog-content').querySelectorAll('[data-truth-output]:checked')].map(input=>input.dataset.truthOutput)});
 const update=()=>{const selected=selections(),bits=choices.inputs.filter(input=>selected.inputIds.includes(input.id)).reduce((sum,input)=>sum+input.width,0),valid=bits>0&&bits<=8&&selected.outputNames.length>0&&selected.outputNames.length<=32;$('truth-generate').disabled=!valid;$('truth-selection-status').textContent=valid?`${2**bits} rows · ${bits} input bits · ${selected.outputNames.length} output columns. Each row starts independently; logic hazards and sequential behavior need a transient run.`:'Choose 1–8 input bits and 1–32 output columns.';};
 $('dialog-content').querySelectorAll('input[type="checkbox"]').forEach(input=>input.onchange=update);update();
 $('truth-generate').onclick=()=>{const selected=selections();preparing=true;runTask=executeTruthTable(selected).finally(()=>{preparing=false;$('run-btn').disabled=false;$('stop-btn').disabled=true;$('truth-table-btn').disabled=false;});};
}

async function executeTruthTable({inputIds,outputNames}){
 const snapshot=clone(project),startedAt=new Date().toISOString(),task={cancelled:false};truthTableTask=task;
 const checkCancelled=()=>{if(task.cancelled)throw Object.assign(new Error('Truth table cancelled.'),{status:'cancelled'});};
 $('run-btn').disabled=true;$('stop-btn').disabled=false;$('truth-table-btn').disabled=true;
 showDialog('Generating truth table','<p id="truth-progress" role="status">Starting the digital worker…</p><div class="dialog-actions"><button id="truth-stop">Stop</button></div>');$('truth-stop').onclick=stopExperiment;
 try{
  const generated=generateNetlist(snapshot),simulationHash=await hashText(JSON.stringify(generated.simulation));
  checkCancelled();
  const result=await engine.runTruthTable(generated,{inputIds,outputNames,timeoutMs:30000,onLog:message=>{if($('truth-progress'))$('truth-progress').textContent=message;}});
  checkCancelled();
  const labels=new Map((generated.measurements??[]).filter(m=>m.vector).map(m=>[m.vector.toLowerCase(),m.label]));
  result.outputs=result.outputs.map(output=>({...output,label:labels.get(output.name.toLowerCase())??output.name}));
  const record={id:uid('table'),kind:'truth-table',status:'completed',projectId:snapshot.id,revision:snapshot.revision,projectSnapshot:snapshot,startedAt,completedAt:new Date().toISOString(),simulation:clone(generated.simulation),simulationHash,inputIds:[...inputIds],outputNames:[...outputNames],result};
  const valid=validateTruthTables([record],validateProject)[0];truthTables.push(valid);const removed=truthTables.length>4;if(removed)truthTables.shift();scheduleSave(true);
  if($('dialog').open&&$('dialog-title').textContent==='Generating truth table')showTruthTableRecord(valid);
  status(`Truth table completed: ${result.rows.length} rows from revision ${snapshot.revision}. Saved with the project.${removed?' The oldest table was removed; the latest four are kept.':''}`);
 }catch(error){if($('dialog').open&&$('dialog-title').textContent==='Generating truth table')showDialog('Truth table stopped',`<div class="notice ${error.status==='cancelled'?'':'error'}">${esc(error.message)}</div><button id="truth-retry">Return to truth-table setup</button>`);if($('truth-retry'))$('truth-retry').onclick=showTruthTables;status(error.message);}finally{if(truthTableTask===task)truthTableTask=null;}
}

