function showExamples(){
 const entries=EXAMPLES.map((example,index)=>({example,index,goals:exampleGoals(example)}));
 showDialog('Choose an experiment',`<p class="helper" style="margin:0 0 18px">Choose what you want to learn, then open a complete working circuit. Loading an example replaces the working circuit.</p><div class="example-goal-filters" aria-label="Filter examples by goal"><button type="button" data-example-goal="all" aria-pressed="true">All experiments</button>${EXAMPLE_GOALS.map(goal=>`<button type="button" data-example-goal="${goal.id}" aria-pressed="false">${esc(goal.title)}</button>`).join('')}</div><div class="examples-grid">${entries.map(({example:e,index,goals})=>`<button class="example-card" data-example="${e.id}" data-example-goals="${goals.join(' ')}"><span class="eyebrow">EXPERIMENT ${String(index+1).padStart(2,'0')} / ${esc(e.category??'ANALOG')}</span><strong>${esc(e.title)}</strong><small>${esc(e.description??e.question)}</small></button>`).join('')}</div>`);
 $('dialog-content').querySelectorAll('[data-example-goal]').forEach(button=>button.onclick=()=>{const goal=button.dataset.exampleGoal;$('dialog-content').querySelectorAll('[data-example-goal]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));$('dialog-content').querySelectorAll('[data-example]').forEach(card=>card.hidden=goal!=='all'&&!card.dataset.exampleGoals.split(' ').includes(goal));});
 $('dialog-content').querySelectorAll('[data-example]').forEach(button=>button.onclick=()=>{const e=EXAMPLES.find(example=>example.id===button.dataset.example);$('dialog').close();confirmReplace(`Load ${e.title}?`,()=>replaceProject(e.create(),`Loaded ${e.title}. Configure the question and press Run.`,[],{exampleId:e.id}));});
}
async function exportWorkingSimulation(){
 const snapshot=clone(project),generated=generateNetlist(snapshot);if(generated.diagnostics.some(d=>d.severity==='error'))throw new Error('Fix circuit errors before exporting a runnable plan. See the inspector checks.');
 const coordinated=snapshot.analysis.type==='tran'&&snapshot.analysis.solver==='coordinated';
 if(hasDigital(snapshot)||coordinated){
  const coordinatedPlan=coordinated?compileCoordinated(snapshot,generated):null,simulation=generated.simulation?clone(generated.simulation):null,run=activeRun(),matching=run?.projectId===snapshot.id&&run.revision===snapshot.revision,analogNetlists=clone(matching?run.result?.analogNetlists??[]:[]);
  const [netlistHash,simulationHash]=await Promise.all([hashText(generated.netlist),hashText(JSON.stringify(coordinatedPlan??simulation))]);
  const payload={format:'CircuitBenchSimulationPlan',formatVersion:1,appVersion:VERSION,project:snapshot,netlist:generated.netlist,netlistHash,simulation,...(simulation?{simulationRole:'digital/mixed-signal partition'}:{}),...(coordinatedPlan?{coordinatedPlan}:{}),simulationHash,simulationHashRole:coordinatedPlan?'coordinated execution plan':'digital/mixed-signal partition',analogNetlists,note:'The compiled plan starts from this captured project’s initial source settings. Project backups and capture evidence retain applied continuous-session commands. Digital components are not standalone SPICE devices.'};
  download(filename(snapshot.title)+'-simulation-plan.json',JSON.stringify(payload,null,2),'application/json');status(`${coordinated?'Coordinated execution':'Digital / mixed-signal partition'} plan downloaded from revision ${snapshot.revision}. Save backup preserves the project and its results.`);return payload;
 }
 download(filename(snapshot.title)+'.cir',generated.netlist,'text/plain');status('SPICE netlist downloaded with exact model definitions and analysis settings.');
}
function exportProject(){download(filename(project.title)+'.circuitbench.json',JSON.stringify(envelope(),null,2),'application/json');status('Project backup downloaded, including saved raw runs, truth tables and timing measurements. Autosave remains local to this browser.');}
async function importProjectFile(file){if(!file)return;if(file.size>256*1024*1024)throw new Error('Project file exceeds the 256 MB limit.');const input=safeEnvelope(JSON.parse(await file.text()),validateProject);for(const run of input.runs)run.importedFromBackup=true;for(const table of input.truthTables)table.importedFromBackup=true;for(const timing of input.timingMeasurements)timing.importedFromBackup=true;for(const study of input.analogExperiments)study.importedFromBackup=true;for(const record of input.captureRecords)record.run.importedFromBackup=true;for(const record of input.measurementRecords)record.importedFromBackup=true;for(const study of input.stepStudies)study.importedFromBackup=true;confirmReplace(`Open ${input.project.title}?`,()=>replaceProject(input.project,'Project opened. Its original disk file will not be changed.',input.runs,input));}
async function importSpiceFile(file){if(!file)return;if(file.size>200000)throw new Error('SPICE file exceeds the 200 kB import limit.');const text=await file.text(),validation=validateImportedNetlist(text);if(validation.diagnostics.some(d=>d.severity==='error')){showDialog('SPICE import needs attention',`<p>Nothing was replaced. This importer accepts a documented analog subset.</p>${validation.diagnostics.map(d=>`<div class="notice ${d.severity==='error'?'error':''}">${esc(d.message)}</div>`).join('')}`);return;}const p=newProject(file.name.replace(/\.[^.]+$/,''));p.workspace='netlist';p.netlistText=text;if(validation.analysis)Object.assign(p.analysis,validation.analysis);confirmReplace(`Import ${file.name}?`,()=>replaceProject(p,'SPICE imported into a netlist workspace. Original schematic layout is not reconstructed.'));}
function showReport(){const run=activeRun(),p=run?.projectSnapshot??project;reportHTML=createReport({project,run,schematic:p.workspace==='schematic'?editor.exportSVG(p):'',plot:run?.result?plot.getSVG():'',baseline:plot.baseline,timingMeasurements,analogExperiments,captureRecords,measurementRecords,stepStudies});showDialog('Analysis report',`<div class="dialog-actions" style="margin:0 0 14px"><a id="download-report" class="download-button">Download HTML report</a><button id="print-report" class="primary">Print / save PDF</button></div><iframe title="Printable CircuitBench analysis report" class="report-frame" id="report-frame"></iframe>`);$('report-frame').srcdoc=reportHTML;if(reportURL)URL.revokeObjectURL(reportURL);reportURL=URL.createObjectURL(new Blob([reportHTML],{type:'text/html'}));$('download-report').href=reportURL;$('download-report').download=filename(p.title)+'-analysis.html';$('download-report').onclick=()=>status('Analysis report download requested.');$('print-report').onclick=()=>{$('report-frame').contentWindow.focus();$('report-frame').contentWindow.print();};}
function showHelp(){showDialog('At the bench · operating guide',`<div class="help-content"><p><strong>CircuitBench v${VERSION}</strong> is a private analog, digital and coordinated mixed-signal electronics workbench. Place components → connect pins → choose an experiment → run → measure → change a value → compare → save.</p><div class="object-actions"><button type="button" data-check-installation>Check installation</button></div><p class="helper">The workbench strip identifies Running, Paused and saved results. Displays follow Latest or Cursor A; Return to latest changes the view without changing the circuit.</p><h3>Your first minute</h3><ol><li>Open <strong>Examples → RC low-pass filter</strong>.</li><li>Choose <strong>Run experiment</strong>. The plot shows magnitude and phase from ngspice.</li><li>Choose <strong>Pin baseline</strong>, select C1, and change its capacitance from 100n to 220n.</li><li>Run again. The dashed curve keeps the old response; the cutoff moves lower.</li><li>Choose <strong>Save backup</strong>. Use <strong>Project → Open project</strong> to reopen it.</li></ol><h3>Draw & connect</h3><p>Choose a component, then click the grid. Use <strong>Wire</strong> and click a pin, optional bend points, and another pin. A snap marker confirms a real endpoint. Crossing lines stay separate. Use <strong>Junction</strong> at a crossing to join them explicitly. Moving and rotating components preserves endpoint connections. While wiring, matching destinations are marked. An incompatible analog/digital or bus-width connection offers an explicit ADC, DAC, Slice or Join where applicable.</p><p>Use <strong>Build…</strong> beside an inspector pin to attach a red HIGH indicator, probe a bus bit, or add a matching decoder and seven-segment display. Each construction action is one undoable edit. Circuit checks offer <strong>Show on schematic</strong> actions and only suggest an alternate solver after checking the complete circuit.</p><p>Shift-click adds to a selection; drag empty space in Select mode to select an area. Wire bend handles appear when a wire is selected. Labels with the same name connect electrically. All Ground symbols identify SPICE node 0.</p><h3>Keyboard & precise editing</h3><table><tbody>${[['1 / 2 / 3 / 4','Select / Wire / Pan / Probe'],['Esc','Cancel current drawing action'],['R / M','Rotate / mirror selection'],['F','Fit circuit'],['Arrow keys','Move selected objects by one grid step'],['Ctrl/Cmd+C, V, D','Copy, paste, duplicate'],['Delete / Backspace','Delete selected objects'],['Ctrl/Cmd+Z / Shift+Z','Undo / redo'],['Ctrl/Cmd+Enter','Run experiment'],['Ctrl/Cmd+S','Download a project backup'],['?','This guide']].map(([k,v])=>`<tr><td><kbd>${esc(k)}</kbd></td><td>${esc(v)}</td></tr>`).join('')}</tbody></table><p>The inspector offers numeric X/Y, rotate/mirror, duplicate/delete, pin measurements, and <strong>Connect pins by name</strong>. Tab reaches components and pins in the canvas; use Enter to activate the current tool.</p><h3>Read the results</h3><p>AC plots show magnitude in <strong>dBV</strong> for voltage (reference 1 V), or dBA for current (reference 1 A), plus phase in degrees. With a 1 V AC input, the output dBV also equals voltage gain in dB. Select V or A to keep vertical units consistent. Wheel zooms, Pan drags, and Cursor A/B measure raw sample positions; Δx and Δvalue appear below. Baselines are dashed and retain their original circuit revision.</p><p>Choose <strong>Values</strong> for numeric readouts, <strong>Run history</strong> for recorded experiments, and <strong>Netlist & diagnostics</strong> for exact inputs and warnings. CSV exports full raw results, including real and imaginary AC values. Plot simplification never changes raw data.</p><h3>Digital & mixed-signal experiments</h3><p>Choose a digital example or place parts from the digital library. Digital components use transient analysis. Logic states are <strong>0</strong> (low), <strong>1</strong> (high), <strong>X</strong> (unknown or conflicting drivers), and <strong>Z</strong> (high impedance). Clocks and propagation delays generate event-driven timing traces. Digital pins use Logic probes; the mixed plot puts voltage and logic on one time axis.</p><h3>Buses, state and truth tables</h3><p>Bus input, timed Pattern, Register, Counter and Multiplexer parts use words from 1 to 8 bits. A displayed word is most-significant bit first; bit 0 is the least-significant bit. Wires and labels require matching widths. Use <strong>Slice</strong> to select a bit or field and <strong>Join</strong> to combine fields: A supplies the low bits, B the high bits. Type exact-width words such as 10XZ, or known values with 0b, 0x or 0d prefixes.</p><p>Registers and counters update on a rising clock edge. Their reset is synchronous and active high; reset takes priority over enable. Set the initial word and output delay in the inspector. Pattern rows use time,word pairs beginning at time 0, separated by semicolons or newlines. Set Repeat to 0 for a one-shot sequence.</p><p>A <strong>Truth table (LUT)</strong> component defines every input combination, with 1–4 input bits and 1–8 output bits. Select the component and choose <strong>Edit truth table</strong> for the row editor. The experiment-level <strong>Truth table</strong> button enumerates up to 8 selected constant input bits (256 rows) and 32 output columns through the digital engine. Clocks, patterns, memory and mixed-signal circuits require transient runs. Each table retains its circuit revision, execution plan and engine identity; the latest four tables are kept in autosave and project backups. Download CSV for the rows or table evidence for the full record.</p><p>Bus lanes preserve leading zeros and X/Z bits. Use a Slice and a scalar probe to inspect one bit. Word lanes and analog signals can share the same time axis. A truth table records settled behavior; use transient runs to inspect propagation delays and hazards.</p><p>Use an explicit <strong>ADC bridge</strong> to translate an analog voltage into logic and a <strong>DAC bridge</strong> to drive an analog circuit from logic. Set their thresholds and output voltages in the inspector. Select <strong>Coordinated transient</strong> for analog/digital feedback and multibit conversion. Its stateful analog solver supports R/C/L and independent voltage/current sources, advancing with digital logic on a shared timeline. The ngspice mixed mode remains feed-forward. Unknown/high-impedance DAC inputs are reported; multibit DACs hold their explicit initial code until the first known input. Gate models describe logical behavior, not a manufacturer IC or its power consumption.</p><h3>Seven-segment displays & converters</h3><p>The <strong>Seven-segment display</strong> is a working eight-bit digital part: bit 0 drives segment a, bits 1–6 drive b–g, and bit 7 drives the decimal point. Choose active-high or active-low. Its schematic symbol and readout follow the selected run and Cursor A; X and Z stay distinct. A <strong>Hex / BCD decoder</strong> converts a four-bit code plus a decimal-point input into the segment word. Open the seven-segment counter example to see them together.</p><p><strong>Multibit ADC</strong> and <strong>Multibit DAC</strong> support 2–8 bits. Set input/output ranges, ADC sample period and conversion delay, and DAC rise/fall times. ADCs clip to the range and round to the nearest unsigned code; code 0 and the maximum code map to the range endpoints. These are behavioral converter models without noise, loading, aperture jitter or physical glitches.</p><p>Save backup retains circuit and results. Export simulation plan records digital/mixed-signal inputs; standalone SPICE import/export remains an analog feature. In ngspice feed-forward mode, analog samples added at digital event times are identified as interpolated. Coordinated mode records accepted numerical states and digital events without replay interpolation.</p><h3>Timing measurements</h3><p>After a digital or mixed-signal transient run, choose <strong>Timing</strong> above the results. Select propagation delay, pulse width, period, frequency or duty cycle, a signal or bus bit, edge polarity and time window. Timing uses preserved digital events. A direct 0→1 or 1→0 change is an edge; X/Z transitions are not guessed. Incomplete pairs and uncertain intervals stay visible without a numerical value.</p><p>Each saved measurement retains its source run, circuit revision, selected events and assumptions. It remains available if that run is removed from history. The latest 12 measurements are retained within a separate evidence-size limit; export CSV or timing evidence, or use Save backup. Reports include retained timing records with their original run and revision clearly identified. Instrument measurements can check explicit setup/hold constraints after a run; physical metastability is not simulated.</p><h3>Operate sources at the schematic</h3><p>Select a source and choose <strong>Pin beside schematic</strong>. The pinned control shows its initial setting, confirmed live drive, recorded drive at the displayed time, and queued changes. The digital source’s dedicated button toggles its starting setting while idle, or its live drive during continuous simulation. Selection and dragging keep their usual meaning.</p><p>Enable <strong>Momentary: hold HIGH, release LOW</strong> for a one-bit digital source. In continuous simulation, hold its button or dedicated button with a pointer, Space or Enter. Releasing, cancelling a pointer or leaving the page returns the source LOW. A paused press and release can share one simulation time; Step or Resume computes the response. Wall-clock hold time does not specify a simulated pulse duration. Pinning and momentary preferences are saved with the project without changing its electrical initial settings.</p><h3>Continuous simulation</h3><p>Choose <strong>Continuous…</strong>, an update interval and a recent-history window. One coordinated worker retains capacitor charge, inductor current, clocks, registers and pending events across batches. <strong>Pause</strong> preserves state, <strong>Step</strong> advances one bounded batch, and <strong>Resume</strong> continues. <strong>Live inputs</strong> changes DC voltage/current and constant logic/bus sources at the next completed boundary; the history records each change.</p><p><strong>Stop & keep results</strong> preserves the recent window and releases the worker. Editing the schematic stops the session. History is bounded to 30,000 points, one million dense values and 250,000 digital events; the safe session timeline ends at 9,000 simulated seconds. The update interval is a simulation target, not a wall-clock speed guarantee. Backups retain inspectable completed windows, including input changes, but cannot resume the private numerical solver state. Timing measurements from a stopped window retain that input history independently.</p><h3>Triggers, event stepping and saved captures</h3><p>During continuous simulation, <strong>Next event</strong> pauses at the next settled scheduled digital event within a bounded search. <strong>Run until event</strong> or <strong>Capture…</strong> declares a digital edge or analog threshold and a maximum search duration. A capture also declares pre-trigger and post-trigger time. The session pauses at the requested event or after the post-trigger window, and reports if no event was found.</p><p>Digital X/Z transitions do not become guessed edges. Analog threshold times are located on the accepted numerical step; reduce maximum step to assess their sensitivity. A saved capture contains original retained samples, circuit revision, applied input history and trigger evidence. Missing requested history is shown explicitly. <strong>Captures</strong> opens independent records; View capture does not replace the working circuit or resume a saved solver. CSV and evidence JSON export the saved window.</p><h3>Instrument measurements and reusable setups</h3><p>Choose <strong>Measurements…</strong> for analog rise/fall time, overshoot, settling time, threshold delay, transfer amplitude gain, AC cutoff, or digital setup/hold constraints. Declare the signals, levels, window and relevant tolerance. The results distinguish complete measurements from ambiguous, missing or incomplete evidence. Original sample interpolation methods and numerical details are preserved with each record.</p><p>An active continuous run requires an explicit <strong>Save completed window & measure</strong> action. That creates an immutable snapshot with a separate run identity while the session remains available. A reusable setup saves exact signal identities, levels and window with the project; applying it to an incompatible run gives a diagnostic. Instrument records retain selected raw evidence independently of run history, and project backups and reports include them.</p><h3>Bus bits and linked signals</h3><p>Use <strong>Expand bits</strong> on a recorded bus to inspect its individual 0/1/X/Z lanes. Bit 0 is the least significant bit; expanding changes only the view. Locate a recorded trace to select its matching schematic net, or focus a pin to select its recorded trace. Links require the same project and circuit revision, so older waveforms cannot silently select a different working circuit.</p><h3>Time-step sensitivity</h3><p>After saving a transient analog instrument setup or measurement, choose <strong>Step study…</strong>. Two to four independent coordinated runs use the original maximum step and successive halvings. Each trial restarts from its captured initial source settings and circuit state. Continuous live changes are not replayed.</p><p>Declare an absolute and relative difference tolerance. Adjacent trial measurements are compared without skipping failed or unavailable results; no scalar is invented from an incomplete or multi-occurrence measurement. These differences describe sensitivity to the declared numerical step, not a certified physical-accuracy score. Stop retains attempted trials, and saved study evidence remains available after ordinary run history is removed.</p><h3>Analog experiments</h3><p>Choose <strong>Analog experiments…</strong> for a linear or logarithmic parameter sweep, or a seeded Monte Carlo tolerance study with up to eight varied parameters. A study runs up to 64 fresh sequential trials using the selected solver. Measure final/minimum/maximum/peak-to-peak/time-weighted RMS results, or AC magnitude/phase at a chosen frequency. Use the divider and RC study examples as starting points.</p><p>Each study records its original circuit, exact trial parameters, selected raw samples, engine information and statistics. Failed or cancelled trials remain explicit and are excluded from statistics. Stop retains completed trials. The latest six studies are kept within bounded evidence budgets; CSV, evidence JSON, project backups and reports preserve the results.</p><h3>Models & engineering values</h3><p>All bundled semiconductor models are clearly identified educational generic models, with source and limitations in the inspector. The op amp is supply-bounded but omits frequency rolloff, slew rate, and input common-mode limits. No manufacturer characterization is implied.</p><p>In the schematic inspector, <strong>M = mega</strong>, <strong>m = milli</strong>, k = kilo, u/µ = micro, n = nano, p = pico. Netlists are generated using explicit scientific notation. Imported SPICE follows SPICE semantics: <strong>M and m = milli; Meg = mega</strong>.</p><h3>SPICE import boundary</h3><p>Supported: R/C/L, independent V/I sources, DC/SIN/PULSE/PWL, D/Q/M/S with supported numeric .model definitions, bundled CB_OPAMP, .op, .dc, .ac dec, .tran, .save all, and comments. Imported analysis becomes the experiment settings. No arbitrary .subckt, .param, .include/.lib, .control, shell commands, vendor dialects, digital devices, HDL, PCB data, or schematic reconstruction.</p><h3>Local data & recovery</h3><p>Autosave uses this browser’s IndexedDB, under this origin. It never overwrites an imported disk file. Save backup creates a portable JSON containing the circuit, saved runs, truth tables, timing and instrument measurements, captures, analog studies and time-step studies. The previous autosave can be recovered from Project. Up to 12 runs and four million saved sample positions are retained; older unpinned runs are removed with a notice when needed. A pinned baseline and the current run are protected. Backups up to 256 MB can be reopened. Keep downloadable backups before clearing browser data or changing hostnames.</p><h3>Offline, limits & failure recovery</h3><p>Serve this folder over HTTPS or localhost, visit once, and wait for <strong>Offline ready</strong>. All essential assets are cached locally. A local server can also serve the downloaded release without an internet connection. Opening index.html with file:// is unsupported.</p><p>Each Run starts a fresh bounded experiment; continuous sessions keep one worker alive until Stop or failure. Worker timeouts and result-size limits stop computation explicitly. Circuits have at most 300 components; the coordinated analog partition additionally allows 48 analog nodes, 80 matrix unknowns and 160 elements. ngspice supports the broader analog model library. Reduce the coordinated maximum step and compare results to check backward-Euler numerical damping and convergence.</p><p>If the engine cannot load, the diagnostics identify the requested file and response. Upload every file from the deploy ZIP. To replace a stale cached installation, <a href="./repair/?release=${VERSION}" target="_blank" rel="noopener">refresh cached application files</a>. This refresh leaves local projects and preferences intact.</p><h3>Scope</h3><p>Educational analog, four-state digital, coordinated closed-loop mixed-signal simulation, multibit conversion, working displays and parameter studies. Nonlinear semiconductor feedback in the coordinated solver, HDL/microcontroller execution, PCB layout and collaboration remain future work. See the release docs for model provenance, tests, and deployment details.</p><p class="helper">Engine: ${esc(ENGINE_INFO.name)} ${esc(ENGINE_INFO.version)}, ${esc(ENGINE_INFO.package)} ${esc(ENGINE_INFO.packageVersion)}. No telemetry, account, or external API is required.</p></div>`);}

// All controls are wired to state changes, exports, or explicit dialogs.
$('part-search').oninput=e=>renderParts(e.target.value);$('project-title').onchange=e=>commit(p=>p.title=e.target.value.trim()||'Untitled circuit','Project renamed');$('analysis-type').onchange=e=>commit(p=>{p.analysis.type=e.target.value;if(e.target.value!=='tran')p.analysis.solver='ngspice';},'Analysis selected');$('solver-mode').onchange=e=>commit(p=>p.analysis.solver=e.target.value,'Transient engine selected');for(const k of ['question','notes'])$(k).onchange=e=>commit(p=>p[k]=e.target.value,`${k==='question'?'Question':'Interpretation'} saved`);$('assumptions').onchange=e=>commit(p=>p.assumptions=e.target.value.split('\n').map(s=>s.trim()).filter(Boolean),'Assumptions saved');$('netlist-editor').onchange=e=>commit(p=>p.netlistText=e.target.value,'Netlist updated');
document.querySelectorAll('button[data-mode]').forEach(b=>b.onclick=()=>{editor.setMode(b.dataset.mode);editor.focus();});$('run-btn').onclick=runExperiment;$('stop-btn').onclick=stopExperiment;$('undo-btn').onclick=()=>restoreHistory(undoStack,redoStack,'Undid last edit');$('redo-btn').onclick=()=>restoreHistory(redoStack,undoStack,'Redid last edit');$('rotate-btn').onclick=()=>editor.rotate();$('delete-btn').onclick=()=>editor.delete();$('fit-btn').onclick=()=>editor.fit();$('zoom-in').onclick=()=>editor.zoom(1.25);$('zoom-out').onclick=()=>editor.zoom(.8);
for(const [id,cls] of [['drawer-toggle','drawer-collapsed'],['inspector-toggle','inspector-collapsed']])$(id).onclick=()=>{const collapsed=$('workbench').classList.toggle(cls);$(id).setAttribute('aria-expanded',String(!collapsed));preference(cls,collapsed);};
$('theme').value=preference('theme')??'dark';document.documentElement.dataset.theme=$('theme').value;$('theme').onchange=e=>{document.documentElement.dataset.theme=e.target.value;preference('theme',e.target.value);plot.draw();};$('advanced').checked=preference('advanced')??false;$('advanced').onchange=e=>{preference('advanced',e.target.checked);renderAnalysis();};
$('save-btn').onclick=exportProject;$('open-btn').onclick=()=>$('project-file').click();$('import-spice-btn').onclick=()=>$('spice-file').click();$('project-file').onchange=async e=>{try{await importProjectFile(e.target.files[0]);}catch(err){handleError(err);}finally{e.target.value='';}};$('spice-file').onchange=async e=>{try{await importSpiceFile(e.target.files[0]);}catch(err){handleError(err);}finally{e.target.value='';}};
$('new-btn').onclick=()=>confirmReplace('Start a new empty project?',()=>replaceProject(newProject(),'New empty project created. Choose a part or open an example.'));$('duplicate-project-btn').onclick=()=>{const copy=clone(project);copy.id=uid('project');copy.title+=' — copy';copy.createdAt=new Date().toISOString();copy.revision=0;replaceProject(copy,'Project duplicated with new identity. Run history starts fresh.');};
$('recover-btn').onclick=async()=>{try{const stored=await loadRecovery();if(!stored)throw new Error('No earlier autosave is available yet.');const next=safeEnvelope(stored,validateProject);confirmReplace('Recover the previous autosave?',()=>replaceProject(next.project,'Previous autosave recovered.',next.runs,next));}catch(e){handleError(e);}};
$('export-spice-btn').onclick=()=>exportWorkingSimulation().catch(handleError);$('export-svg-btn').onclick=()=>{if(project.workspace==='netlist')return handleError(new Error('This project is a netlist; it has no reconstructed schematic to export.'));download(filename(project.title)+'.svg',editor.exportSVG(),'image/svg+xml');status('Schematic SVG downloaded.');};$('export-bom-btn').onclick=()=>{if(project.workspace==='netlist')return handleError(new Error('A component list is available for schematic projects. The imported SPICE text contains this netlist’s components.'));download(filename(project.title)+'-components.csv',componentCSV(project),'text/csv');status('Component list downloaded.');};
initializeLiveControls();
$('continuous-next-event').onclick=()=>stepToNextEvent().catch(handleError);$('continuous-capture').onclick=()=>showCaptureSetup('capture').catch(handleError);$('continuous-until').onclick=()=>showCaptureSetup('until').catch(handleError);$('continuous-cancel-capture').onclick=()=>{continuousSession?.cancelCapture();renderCaptureState();status('Armed capture cancelled; the retained session remains available.');};$('capture-history-btn').onclick=showCaptureHistory;$('measurements-btn').onclick=()=>showInstrumentMeasurements();$('step-study-btn').onclick=showStepStudies;
$('continuous-btn').onclick=showContinuousSetup;$('continuous-pause').onclick=()=>{try{if(continuousSession?.state==='paused'){if(!liveInputController?.hasPending(continuousSession))continuousSession.resume();}else continuousSession?.pause();}catch(error){handleError(error);}};$('continuous-step').onclick=()=>stepContinuous().catch(handleError);$('continuous-inputs').onclick=showLiveInputs;$('continuous-stop').onclick=stopContinuous;$('experiments-btn').onclick=showAnalogExperiments;$('timing-btn').onclick=showTimingMeasurements;$('truth-table-btn').onclick=showTruthTables;$('examples-btn').onclick=showExamples;$('start-rc-btn').onclick=()=>{const e=EXAMPLES.find(e=>e.id==='rc-filter')??EXAMPLES.find(e=>/low.pass/i.test(e.title))??EXAMPLES[0];replaceProject(e.create(),'RC filter loaded. Press Run experiment to see its frequency response.',[],{exampleId:e.id});};$('start-digital-btn').onclick=()=>{const e=EXAMPLES.find(e=>e.id==='digital-half-adder')??EXAMPLES.find(e=>hasDigital(e.create()));if(e)replaceProject(e.create(),'Digital example loaded. Run experiment to inspect its logic timing.',[],{exampleId:e.id});};$('help-btn').onclick=showHelp;$('dialog-close').onclick=()=>$('dialog').close();$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('dialog').close();}});
$('results-toggle').onclick=()=>{const collapsed=$('results').classList.toggle('collapsed');$('results-toggle').setAttribute('aria-expanded',String(!collapsed));preference('results-collapsed',collapsed);};document.querySelectorAll('[data-result-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.resultTab));$('baseline-btn').onclick=()=>{const r=activeRun();if(!r?.result)return;baselineId=baselineId===r.id?null:r.id;renderResults();scheduleSave();status(baselineId?'Baseline pinned. Change a value and run again to compare.':'Baseline unpinned.');};$('compare-toggle').onchange=renderResults;$('csv-btn').onclick=()=>{const r=activeRun();if(!r?.result)return;download(filename(project.title)+'-rev'+r.revision+'-'+r.analysis.type+'.csv',csvForRun(r),'text/csv');status('Stored results downloaded, including literal logic states and sampling provenance where applicable.');};$('report-btn').onclick=showReport;
document.addEventListener('click',e=>{if(e.target.closest?.('[data-check-installation]'))showInstallationCheck();});
$('dialog').addEventListener('close',()=>cancelInstallationCheck());
document.addEventListener('click',e=>{if(!$('project-menu').contains(e.target))$('project-menu').open=false;else if(e.target.closest('button'))$('project-menu').open=false;});
document.addEventListener('keydown',e=>{const editing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable,mod=e.ctrlKey||e.metaKey;if(mod&&e.key==='Enter'){e.preventDefault();e.target.blur?.();runExperiment();return;}if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();e.target.blur?.();exportProject();return;}if($('dialog').open||editing||e.defaultPrevented)return;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();restoreHistory(e.shiftKey?redoStack:undoStack,e.shiftKey?undoStack:redoStack,e.shiftKey?'Redid last edit':'Undid last edit');return;}if(e.key==='?'){e.preventDefault();showHelp();}if(!mod&&['1','2','3','4'].includes(e.key)){e.preventDefault();editor.setMode({'1':'select','2':'wire','3':'pan','4':'probe'}[e.key]);editor.focus();}});
window.addEventListener('beforeunload',e=>{if(saveState==='unsaved'||saveState==='saving'||saveState==='error'||engine.running||preparing||studyAbort||continuousSession?.running){e.preventDefault();e.returnValue='';}});
async function setupOffline(){
 const label=$('offline-status');
 if(!('serviceWorker' in navigator)||!window.isSecureContext){label.textContent='Offline cache requires HTTPS / localhost';return;}
 try{
  const registration=await navigator.serviceWorker.register(new URL('./sw-'+VERSION+'.js',document.baseURI),{updateViaCache:'none'});
  const watch=worker=>{if(!worker)return;worker.addEventListener('statechange',()=>{
   if(worker.state==='redundant'){label.textContent='Offline cache installation failed';label.title='A required runtime file could not be downloaded or verified. Upload the complete release and use Help to refresh cached application files.';}
   if(worker.state==='installed'&&navigator.serviceWorker.controller){status('An application update is ready. Save a backup, then close and reopen all CircuitBench tabs to use it.');}
  });};
  registration.addEventListener('updatefound',()=>watch(registration.installing));watch(registration.installing);
  await navigator.serviceWorker.ready;
  const target=registration.active??navigator.serviceWorker.controller;
  if(target){
   const channel=new MessageChannel(),timer=setTimeout(()=>{label.textContent='Offline cache could not be checked';channel.port1.close();},5000);
   channel.port1.onmessage=e=>{
    clearTimeout(timer);channel.port1.close();const data=e.data??{};
    if(data.ready&&data.version===VERSION&&(!/^[a-f0-9]{16}$/.test(loadedBuild??'')||data.build===loadedBuild)){label.textContent='✓ Offline ready · all runtime assets verified';label.title='';}
    else if(data.ready){label.textContent='Cached update needs a reload';label.title='Close all CircuitBench tabs and reopen the application to use the installed release.';}
    else{label.textContent=data.error?'Offline cache failed verification':'Offline cache is still installing…';label.title=String(data.error??'');}
   };
   target.postMessage({type:'CACHE_STATUS'},[channel.port2]);
  }
 }catch(e){label.textContent='Offline cache unavailable';label.title=e.message;}
}
async function boot(){renderParts();if(innerWidth<701){for(const cls of ['drawer-collapsed','inspector-collapsed']){const collapsed=preference(cls)??(cls==='drawer-collapsed');$('workbench').classList.toggle(cls,collapsed);$(cls==='drawer-collapsed'?'drawer-toggle':'inspector-toggle').setAttribute('aria-expanded',String(!collapsed));}}else{for(const cls of ['drawer-collapsed','inspector-collapsed'])if(preference(cls))$('workbench').classList.add(cls);}if(preference('results-collapsed')){$('results').classList.add('collapsed');$('results-toggle').setAttribute('aria-expanded','false');}try{const stored=await loadCurrent();if(stored){const data=safeEnvelope(stored,validateProject);project=data.project;runs=data.runs;restoredRunIds=new Set(runs.map(run=>run.id));truthTables=data.truthTables;timingMeasurements=data.timingMeasurements;analogExperiments=data.analogExperiments;captureRecords=data.captureRecords;measurementRecords=data.measurementRecords;stepStudies=data.stepStudies;activeRunId=data.activeRunId;baselineId=data.baselineId;status('Recovered your locally saved project.');}setSaveState('saved');}catch(e){setSaveState('error','! Session only');status(`Local project recovery failed: ${e.message}. Use a downloaded backup to reopen your work.`);}render();requestAnimationFrame(()=>editor.fit());setupOffline();}
boot().catch(handleError);
